const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto'),Zip=require('adm-zip');
const core=require('./core.cjs');const {assert,contained,atomicJSON,readJSON}=core;
const TOOLS=[];
const add=(group,id,name,description,input=null,options=null)=>TOOLS.push({group,id,name,description,input,options});
for(const x of [
 ['rename','Rename instance','Change the displayed name without moving its files.','Name'],
 ['notes','Instance notes','Keep up to 4,000 characters of setup notes.','Notes'],
 ['favorite','Favorite instance','Mark this instance for your favorites filter.','choice',['Yes','No']],
 ['memory','Instance memory','Override global memory for this instance, in MB.','Memory (1024–65536)'],
 ['resolution','Instance resolution','Override the window size for this instance.','Width x height'],
 ['reset-launch','Reset launch overrides','Use global memory and window size again.'],
 ['clone-config','Clone configuration','Create a new instance with mods and settings, excluding worlds.'],
 ['clone-worlds','Clone with worlds','Create a separate copy of mods, settings and worlds.'],
 ['backup','Back up user files','Save mods, config, worlds, skins and emotes as a ZIP. Game runtimes are excluded.'],
 ['restore','Restore backup as new','Import a launcher backup into a new instance; existing instances stay intact.']])add('Instances',...x);
for(const x of [
 ['overview','Instance overview','Read version, loader, launch overrides and notes.'],['disk','Disk usage','Show file counts and space used by each user-content folder.'],['hashes','Mod SHA-256 audit','Calculate the actual hashes of enabled and disabled JARs.'],['duplicates','Duplicate Fabric IDs','Inspect root fabric.mod.json IDs and identify duplicate enabled mods.'],['missing','Missing tracked files','Find missing files recorded in content.json.'],['disabled','Disabled content report','List disabled mods, shader packs, resources and datapacks.'],['log-errors','Recent log errors','Find recent warning, error and exception lines with token redaction.'],['crash','Latest crash report','Read the latest crash report with token redaction.'],['options-diff','Performance settings diff','Compare current options with the saved performance backup.'],['bundle','Ready bundle audit','Read the exact pinned ready-instance manifest.']])add('Diagnostics',...x);
const FOLDERS={mods:'mods',config:'config',worlds:'saves',resources:'resourcepacks',shaders:'shaderpacks',screenshots:'screenshots',logs:'logs',emotes:'emotes',skins:'CustomSkinLoader/LocalSkin',crashes:'crash-reports'};
for(const [id,folder]of Object.entries(FOLDERS))add('Folders','folder-'+id,'Open '+id+' folder','Open '+folder+' for the selected instance.');
for(const x of [
 ['mods-csv','Export mod list CSV','Save mod names, providers, paths and enabled state.'],['content-json','Export content manifest','Save the full tracked and imported content list as JSON.'],['worlds-csv','Export world list CSV','Save world names, file counts and disk usage.'],['emotes-json','Export emote inventory','Save installed emote paths and SHA-256 hashes.'],['settings-json','Export launcher preferences','Save preferences with provider keys and authentication excluded.'],['instance-json','Export instance manifest','Save portable instance metadata without local Java paths.'],['skin-png','Export equipped skin','Copy the selected username’s equipped local PNG.','Minecraft username'],['log-txt','Export recent log','Save the recent game log after token redaction.'],['support-zip','Create support bundle','Save diagnostics and a redacted log, excluding worlds, credentials and configuration contents.'],['screenshots-zip','Export screenshots','Save this instance’s screenshots as a ZIP.']])add('Exports',...x);
const PREFS={sort:['recent','name','version'],favoritesOnly:['Yes','No'],compact:['Yes','No'],reduceMotion:['Yes','No'],largeText:['Yes','No'],confirmLaunch:['Yes','No'],rememberInstance:['Yes','No'],readyProfile:['balanced','low','maximum'],showDisabled:['Yes','No'],hideNames:['Yes','No']};
for(const x of [
 ['sort','Instance sorting','Sort by last played, name or Minecraft version.'],['favoritesOnly','Favorite instance filter','Show favorite instances only, or show your full library.'],['compact','Compact instance cards','Use a denser instance grid.'],['reduceMotion','Reduced motion','Stop preview animation, turntables and interface transitions.'],['largeText','Larger text','Increase interface text for easier reading.'],['confirmLaunch','Launch confirmation','Review the instance name and offline mode before launching.'],['rememberInstance','Remember selected instance','Choose whether the launcher remembers your instance between sessions.'],['readyProfile','Default ready profile','Choose the initial optimization profile on the Ready instances page.'],['showDisabled','Show disabled content','Include or hide disabled items in Installed content.'],['hideNames','Hide account name','Hide the account name in the sidebar while recording or sharing your screen.']])add('Preferences','pref-'+x[0],x[1],x[2],'choice',PREFS[x[0]]);
const USER_DIRS=['mods','config','saves','resourcepacks','shaderpacks','screenshots','emotes','CustomSkinLoader'];
const USER_FILES=['options.txt','servers.dat','content.json','player-style.json','boralances-wings.json','boralances-emotes.json','boralances-capes.json','.boralances-options-backup.json'];
const allowed=rel=>rel.toLowerCase()!=='config/boralances-client/chat-bridge.json'&&(USER_FILES.includes(rel)||USER_DIRS.includes(rel.split('/')[0]));
const sanitize=i=>Object.fromEntries(['name','minecraft','loader','loaderVersion','notes','favorite','launchOverrides','presetId','presetPrepared','performanceProfile'].filter(k=>Object.hasOwn(i,k)).map(k=>[k,i[k]]));
const redact=text=>String(text).replace(/((?:access[_ -]?token|refresh[_ -]?token|api[_ -]?key|authorization|password)["'\s:=]+)(?:Bearer\s+)?[^\s,"'}]+/gi,'$1[redacted]').replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g,'[redacted JWT]');
async function walk(root,rel=''){
 const folder=rel?await contained(root,rel):root,entries=await fs.readdir(folder,{withFileTypes:true}).catch(e=>{if(e.code==='ENOENT')return [];throw e;}),out=[];
 for(const e of entries){const next=rel?rel+'/'+e.name:e.name,file=await contained(root,next),stat=await fs.lstat(file);assert(!stat.isSymbolicLink(),'Linked files are not included: '+next);if(stat.isDirectory())out.push(...await walk(root,next));else if(stat.isFile())out.push({path:next,size:stat.size,modified:stat.mtimeMs});assert(out.length<=10000,'Folder contains too many files for this tool.');}return out;
}
async function userFiles(directory,worlds=true){let out=[];for(const dir of USER_DIRS)if(worlds||dir!=='saves')out.push(...await walk(directory,dir));for(const rel of USER_FILES){const file=await contained(directory,rel),s=await fs.stat(file).catch(()=>null);if(s?.isFile())out.push({path:rel,size:s.size});}return out.filter(f=>allowed(f.path));}
function inspectBackup(file){const zip=new Zip(file),entries=zip.getEntries(),meta=entries.find(e=>e.entryName==='boralances-backup.json');assert(meta,'This is not a Boralances user-file backup.');assert(meta.header.size<65536,'Backup metadata is too large.');const info=JSON.parse(meta.getData().toString('utf8'));assert(info.format===1&&core.LOADERS.has(info.instance?.loader)&&typeof info.instance.minecraft==='string'&&/^[a-zA-Z0-9._-]{1,40}$/.test(info.instance.minecraft),'Invalid backup metadata.');let size=0;assert(entries.length<=10002,'Too many backup entries.');const files=[],names=new Set();for(const e of entries){if(e.isDirectory||e===meta)continue;const rel=core.safeRelative(e.entryName);assert(!names.has(rel.toLowerCase()),'Duplicate backup path.');names.add(rel.toLowerCase());assert(allowed(rel),'Unsupported backup entry: '+rel);assert(((e.attr>>>16)&0xf000)!==0xa000,'Linked archive entries are not supported.');size+=e.header.size;assert(size<=1024*1024*1024,'Backup is larger than 1 GB.');files.push({rel,entry:e});}return {instance:sanitize(info.instance),files};}
async function archive(directory,instance,worlds=true){const zip=new Zip(),files=await userFiles(directory,worlds);assert(files.reduce((n,f)=>n+f.size,0)<=1024*1024*1024,'Backup is larger than 1 GB.');zip.addFile('boralances-backup.json',Buffer.from(JSON.stringify({format:1,instance:sanitize(instance)},null,2)));for(const f of files)zip.addFile(f.path,await fs.readFile(await contained(directory,f.path)));return zip.toBuffer();}
async function restore(file,instances){const backup=inspectBackup(file),id=crypto.randomUUID(),stage=await contained(instances,'.tools-'+id),target=await contained(instances,id);await fs.mkdir(stage);try{for(const f of backup.files){const dest=await contained(stage,f.rel);await fs.mkdir(path.dirname(dest),{recursive:true});await fs.writeFile(dest,f.entry.getData(),{flag:'wx'});}const saved=backup.instance;const i={...saved,launchOverrides:validateOverrides(saved.launchOverrides),name:String(saved.name||'Restored instance').slice(0,70)+' · restored',id,created:Date.now(),installedVersion:null};await atomicJSON(path.join(stage,'instance.json'),i);await fs.rename(stage,target);return i;}finally{await fs.rm(stage,{recursive:true,force:true});}}
function validateOverrides(value={}){assert(value&&typeof value==='object','Invalid launch overrides.');const result={};for(const k of ['memory','width','height'])if(value[k]!==undefined){const n=Number(value[k]),range=k==='memory'?[1024,65536]:k==='width'?[640,7680]:[480,4320];assert(Number.isInteger(n)&&n>=range[0]&&n<=range[1],'Invalid '+k+' override.');result[k]=n;}return result;}
const csv=rows=>rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\r\n');
async function log(directory){for(const rel of ['logs/latest.log','launcher-latest.log']){const f=await contained(directory,rel);try{const stat=await fs.stat(f),h=await fs.open(f,'r');try{const b=Buffer.alloc(Math.min(stat.size,120000));await h.read(b,0,b.length,Math.max(0,stat.size-b.length));return redact(b.toString());}finally{await h.close();}}catch(e){if(e.code!=='ENOENT')throw e;}}return 'No log available.';}
async function report(id,directory,instance,content,assets){
 if(id==='overview')return {...sanitize(instance),installedVersion:instance.installedVersion,lastPlayed:instance.lastPlayed||null};
 if(id==='disk'){const rows=[];for(const folder of USER_DIRS){const files=await walk(directory,folder);rows.push({folder,files:files.length,bytes:files.reduce((n,f)=>n+f.size,0)});}return rows;}
 if(id==='hashes')return Promise.all((await walk(directory,'mods')).filter(f=>/\.jar(?:\.disabled)?$/i.test(f.path)).map(async f=>({...f,sha256:crypto.createHash('sha256').update(await fs.readFile(await contained(directory,f.path))).digest('hex')})));
 if(id==='duplicates'){const byId=Object.create(null),unreadable=[];for(const f of (await walk(directory,'mods')).filter(f=>f.path.endsWith('.jar')))try{const z=new Zip(await contained(directory,f.path)),entry=z.getEntry('fabric.mod.json');if(entry){const m=JSON.parse(entry.getData());(byId[m.id]||=[]).push({path:f.path,version:m.version});}}catch{unreadable.push(f.path);}return {duplicates:Object.entries(byId).filter(([,v])=>v.length>1).map(([id,files])=>({id,files})),unreadable,scope:'Root Fabric module IDs; nested modules and Forge metadata are excluded.'};}
 if(id==='missing'){const missing=[];for(const x of content)if(!await fs.stat(await contained(directory,x.path+(x.disabled?'.disabled':''))).then(s=>s.isFile()).catch(()=>false))missing.push(x);return missing;}
 if(id==='disabled')return content.filter(x=>x.disabled);
 if(id==='log-errors')return (await log(directory)).split(/\r?\n/).filter(x=>/warn|error|exception|fatal/i.test(x)).slice(-150);
 if(id==='crash'){const files=(await walk(directory,'crash-reports')).filter(f=>f.path.endsWith('.txt')).sort((a,b)=>b.modified-a.modified);if(!files.length)return {message:'No crash reports.'};const file=files[0];assert(file.size<=4*1024*1024,'Crash report too large. Open the crash folder instead.');return {file:file.path,text:redact(await fs.readFile(await contained(directory,file.path),'utf8'))};}
 if(id==='options-diff'){const b=await readJSON(await contained(directory,'.boralances-options-backup.json'),null);assert(b,'Apply a performance profile first to create a backup.');const parse=s=>Object.fromEntries((s||'').split(/\r?\n/).filter(l=>l.includes(':')).map(l=>[l.slice(0,l.indexOf(':')),l.slice(l.indexOf(':')+1)]));const before=parse(b.original),after=parse(await fs.readFile(await contained(directory,'options.txt'),'utf8').catch(()=>''));return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>before[k]!==after[k]).map(key=>({key,before:before[key]??null,after:after[key]??null}));}
 if(id==='bundle'){assert(instance.presetId&&['26.3','1.21.11','1.21.1','1.20.1'].includes(instance.presetId),'This instance was not created from a bundled ready preset.');return readJSON(path.join(assets,instance.presetId+'.json'),null);}
 throw new Error('Unknown report.');
}
async function registerTools(ctx){const {handle,task,getInstance,listContent,editable,settings,saveSettings,dialog,win,data,shell}=ctx;
 handle('tools-list',()=>TOOLS);
 handle('tools-run',p=>task('Launcher tools',async()=>{
  const tool=TOOLS.find(x=>x.id===p.id);assert(tool,'Unknown launcher tool.');
  if(tool.group==='Preferences'){const key=p.id.slice(5);assert(PREFS[key].includes(p.value),'Choose a listed preference.');settings().tools={...settings().tools,[key]:['Yes','No'].includes(p.value)?p.value==='Yes':p.value};await saveSettings();return {message:tool.name+' saved.'};}
  const instances=path.join(data,'instances');
  if(p.id==='restore'){const r=await dialog.showOpenDialog(win(),{properties:['openFile'],filters:[{name:'Boralances backup',extensions:['zip']}]});if(r.canceled)return null;const i=await restore(r.filePaths[0],instances);return {instance:i,message:'Backup restored into a new instance. Install / repair downloads its game.'};}
  const {instance,directory}=await getInstance(p.instanceId);
  const save=async(buffer,extension)=>{const r=await dialog.showSaveDialog(win(),{defaultPath:p.id+'.'+extension,filters:[{name:tool.name,extensions:[extension]}]});if(r.canceled)return null;await fs.writeFile(r.filePath,buffer);return {message:'Saved '+path.basename(r.filePath)};};
  if(tool.group==='Folders'){const folder=await contained(directory,FOLDERS[p.id.slice(7)]);await fs.mkdir(folder,{recursive:true});const error=await shell.openPath(folder);assert(!error,error);return {message:'Folder opened.'};}
  if(tool.group==='Diagnostics')return {report:await report(p.id,directory,instance,await listContent(instance.id),ctx.assets)};
  if(tool.group==='Instances'){
   editable(instance.id);
   if(['clone-config','clone-worlds','backup'].includes(p.id)){const bytes=await archive(directory,instance,p.id!=='clone-config');if(p.id==='backup')return save(bytes,'zip');const temp=await contained(instances,'.clone-'+crypto.randomUUID()+'.zip');try{await fs.writeFile(temp,bytes);const i=await restore(temp,instances);i.name=instance.name.slice(0,70)+' · copy';await atomicJSON(path.join(instances,i.id,'instance.json'),i);return {instance:i,message:'Independent instance copy created. Install / repair downloads its game.'};}finally{await fs.rm(temp,{force:true});}}
   if(p.id==='rename'){const n=String(p.value||'').trim();assert(n.length>0&&n.length<=80,'Name must be 1–80 characters.');instance.name=n;}
   else if(p.id==='notes'){assert(typeof p.value==='string'&&p.value.length<=4000,'Notes must be at most 4,000 characters.');instance.notes=p.value;}
   else if(p.id==='favorite'){assert(['Yes','No'].includes(p.value),'Choose Yes or No.');instance.favorite=p.value==='Yes';}
   else if(p.id==='memory')instance.launchOverrides={...instance.launchOverrides,...validateOverrides({memory:p.value})};
   else if(p.id==='resolution'){const m=/^(\d+)\s*[x×]\s*(\d+)$/.exec(String(p.value));assert(m,'Use width x height, for example 1280x720.');instance.launchOverrides={...instance.launchOverrides,...validateOverrides({width:m[1],height:m[2]})};}
   else if(p.id==='reset-launch')delete instance.launchOverrides;
   else throw new Error('Unsupported instance tool.');
   await atomicJSON(path.join(directory,'instance.json'),instance);return {message:tool.name+' saved.'};
  }
  const content=await listContent(instance.id),json=v=>Buffer.from(JSON.stringify(v,null,2)+'\n');
  if(p.id==='mods-csv')return save(csv([['name','provider','path','enabled'],...content.filter(x=>x.type==='mod').map(x=>[x.name,x.provider,x.path,!x.disabled])]),'csv');
  if(p.id==='content-json')return save(json(content),'json');
  if(p.id==='instance-json')return save(json(sanitize(instance)),'json');
  if(p.id==='settings-json'){const s=settings();return save(json(Object.fromEntries(['theme','offlineName','memory','width','height','snapshots','tools'].map(k=>[k,s[k]]))),'json');}
  if(p.id==='worlds-csv'){const worlds=await fs.readdir(await contained(directory,'saves'),{withFileTypes:true}).catch(e=>{if(e.code==='ENOENT')return [];throw e;}),rows=[];for(const w of worlds)if(w.isDirectory()){const f=await walk(directory,'saves/'+w.name);rows.push([w.name,f.length,f.reduce((n,x)=>n+x.size,0)]);}return save(csv([['world','files','bytes'],...rows]),'csv');}
  if(p.id==='emotes-json')return save(json(await Promise.all((await walk(directory,'emotes')).filter(f=>/\.json$/i.test(f.path)).map(async f=>({...f,sha256:crypto.createHash('sha256').update(await fs.readFile(await contained(directory,f.path))).digest('hex')})))),'json');
  if(p.id==='skin-png'){const u=core.offlineProfile(p.value).name;return save(await fs.readFile(await contained(directory,'CustomSkinLoader/LocalSkin/skins/'+u+'.png')),'png');}
  if(p.id==='log-txt')return save(await log(directory),'txt');
  if(p.id==='screenshots-zip'){const z=new Zip(),files=(await walk(directory,'screenshots')).filter(f=>/\.(png|jpg|jpeg)$/i.test(f.path));assert(files.reduce((n,f)=>n+f.size,0)<=1024*1024*1024,'Screenshot archive exceeds 1 GB.');for(const f of files)z.addFile(f.path,await fs.readFile(await contained(directory,f.path)));return save(z.toBuffer(),'zip');}
  if(p.id==='support-zip'){const z=new Zip();z.addFile('instance.json',json(sanitize(instance)));z.addFile('disk.json',json(await report('disk',directory,instance,content)));z.addFile('mod-hashes.json',json(await report('hashes',directory,instance,content)));z.addFile('recent-log.txt',Buffer.from(await log(directory)));return save(z.toBuffer(),'zip');}
  throw new Error('Unsupported tool.');
 }));
}
module.exports={TOOLS,PREFS,walk,userFiles,archive,inspectBackup,restore,validateOverrides,redact,report,registerTools,sanitize};
